<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { get } from '../api/client'
import { type Page, type Related, type Entity, title, entityLink } from '../types/catalog'
import Pager from '../components/Pager.vue'
const route = useRoute(), ranking = ref<Page<Related>>(), colleagues = ref<Page<Related>>(), commonWorks = ref<Page<Related>>(), person = ref<Entity>(), other = ref<Entity>(), from = ref(''), to = ref(''), role = ref(''), error = ref(''), loading = ref(false)
let controller: AbortController | undefined
const query = () => new URLSearchParams({ ...(from.value ? { yearFrom: from.value } : {}), ...(to.value ? { yearTo: to.value } : {}), ...(role.value ? { roleCodes: role.value } : {}) })
async function rankingPage(page = 1) { const params = query(); params.set('page', String(page)); ranking.value = await get<Page<Related>>(`/analysis/people/ranking?${params}`, controller?.signal) }
async function load(page = 1) { controller?.abort(); controller = new AbortController(); const current = controller; loading.value = true; error.value = ''; try { await rankingPage(page); if (person.value) await choose(person.value) } catch(e) { if (!current.signal.aborted) error.value = e instanceof Error ? e.message : '分析失败' } finally { if (!current.signal.aborted) loading.value = false } }
async function choose(entity: Entity, page = 1) { person.value = entity; commonWorks.value = undefined; other.value = undefined; const params = query(); params.set('page', String(page)); try { colleagues.value = await get<Page<Related>>(`/analysis/people/${encodeURIComponent(entity.uid)}/collaborators?${params}`, controller?.signal) } catch(e) { error.value = e instanceof Error ? e.message : '查询失败' } }
async function showWorks(entity: Entity) { if (!person.value) return; other.value = entity; try { commonWorks.value = await get<Page<Related>>(`/analysis/people/${encodeURIComponent(person.value.uid)}/collaborators/${encodeURIComponent(entity.uid)}/works?${query()}`, controller?.signal) } catch(e) { error.value = e instanceof Error ? e.message : '查询失败' } }
onMounted(async () => { await load(); if (route.query.personUid) { try { await choose(await get<Entity>(`/people/${encodeURIComponent(String(route.query.personUid))}`)) } catch(e) { error.value = e instanceof Error ? e.message : '读取失败' } } }); onUnmounted(() => controller?.abort())
</script>
<template><p class="notice">这里统计已收录本地档案的制作协作。个人观看报告和作品推荐已移到<RouterLink to="/preferences">观看偏好</RouterLink>。</p><section class="page-intro"><p class="eyebrow">PEOPLE & COLLABORATION</p><h1>每一次合作，都有作品为证。</h1><p>按不同作品计数；同一人在一部作品兼任多个岗位，只计一部。此处仅统计制作关系。</p></section><p class="notice">此页保留本地知识库的制作合作查询，已从主导航移除。个人演职员观看统计将在后续看番报告阶段接入；目前可先查看<RouterLink to="/preferences">观看偏好</RouterLink>。</p><form class="toolbar" @submit.prevent="load()"><label>起始年份<input v-model="from" type="number" min="1800" max="2200" placeholder="不限"></label><label>截止年份<input v-model="to" type="number" min="1800" max="2200" placeholder="不限"></label><label class="grow">制作岗位<select v-model="role"><option value="">全部岗位</option><option value="DIRECTOR">监督</option><option value="SCRIPT">脚本</option><option value="MUSIC">音乐</option><option value="CHARACTER_DESIGN">人物设定</option></select></label><button class="primary" :disabled="loading">更新分析</button></form><p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="loading" class="feedback" role="status">正在统计作品与合作…</p><section v-if="ranking" class="panel"><h2>人员作品数量排行</h2><p v-if="!ranking.items.length" class="muted">当前筛选范围内暂无制作记录。</p><div v-if="ranking.items.length" class="table-scroll"><table><caption>制作人员作品数量</caption><thead><tr><th scope="col">排名</th><th scope="col">人员</th><th scope="col">作品数</th><th scope="col">合作记录</th></tr></thead><tbody><tr v-for="(row,i) in ranking.items" :key="row.entity.uid"><td>{{ (ranking.page - 1) * ranking.pageSize + i + 1 }}</td><td><RouterLink :to="entityLink(row.entity)">{{ title(row.entity) }}</RouterLink></td><td>{{ row.workCount }} 部</td><td><button @click="choose(row.entity)">查看合作</button></td></tr></tbody></table></div><Pager :page="ranking.page" :total="ranking.total" :size="ranking.pageSize" @change="load" /></section><section v-if="person && colleagues" class="panel"><h2>{{ title(person) }} 的合作记录</h2><p class="muted">按表格核对共同参与的作品数量，可展开具体作品。</p><p v-if="!colleagues.items.length">暂无共同制作记录。</p><div v-if="colleagues.items.length" class="table-scroll"><table><caption>共同制作记录</caption><thead><tr><th scope="col">合作人员</th><th scope="col">共同作品数</th><th scope="col">作品明细</th></tr></thead><tbody><tr v-for="row in colleagues.items" :key="row.entity.uid"><td><RouterLink :to="entityLink(row.entity)">{{ title(row.entity) }}</RouterLink></td><td>{{ row.workCount }} 部</td><td><button @click="showWorks(row.entity)">核对共同作品</button></td></tr></tbody></table></div><Pager :page="colleagues.page" :total="colleagues.total" :size="colleagues.pageSize" @change="choose(person!, $event)" /></section><section v-if="commonWorks" class="panel"><h2>与 {{ other ? title(other) : '' }} 的共同作品</h2><div v-if="commonWorks.items.length" class="table-scroll"><table><caption>共同作品与双方职务</caption><thead><tr><th scope="col">作品</th><th scope="col">{{ person ? title(person) : '人员 A' }}的职务</th><th scope="col">{{ other ? title(other) : '人员 B' }}的职务</th></tr></thead><tbody><tr v-for="row in commonWorks.items" :key="row.entity.uid"><td><RouterLink :to="entityLink(row.entity)">{{ title(row.entity) }}</RouterLink></td><td>{{ row.rolesA?.join('、') || '职务未知' }}</td><td>{{ row.rolesB?.join('、') || '职务未知' }}</td></tr></tbody></table></div><p v-if="!commonWorks.items.length">无符合条件的共同作品。</p></section></template>
